begin;
insert into auth.sessions(id,user_id) select md5('pgtap-session:'||id::text)::uuid,id from auth.users;
set local search_path=extensions,public,private;
select no_plan();
update private.private_locations set verified_at=now();
update private.commerce_configuration set mode='sandbox';
select ok(not has_table_privilege('authenticated','private.train_locations','SELECT'),'precise locations cannot be read directly');
select ok(not has_function_privilege('anon','public.train_command(text,uuid,jsonb)','EXECUTE'),'anonymous train commands denied');
select ok(not has_function_privilege('authenticated','private.discover_candidates_impl(jsonb,jsonb)','EXECUTE'),'unlimited candidates are not callable');
select ok(not has_table_privilege('authenticated','private.discovery_batches','UPDATE'),'clients cannot reset their allowance');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','role','authenticated','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid)::text,true);
select set_config('test.train',public.train_command('create',null,'{"name":"Test train","symbol":"🚂"}')#>>'{}',true);
select is(public.train_command('list')->0->>'visibility','private','trains are private by default');
reset role;
insert into public.group_members(group_id,profile_id,role,status) values(current_setting('test.train')::uuid,'10000000-0000-0000-0000-000000000002','member','active');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','role','authenticated','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid)::text,true);
select lives_ok($$select public.train_command('location',current_setting('test.train')::uuid,'{"latitude":64.15,"longitude":-21.94,"minutes":15,"recipients":["10000000-0000-0000-0000-000000000002"]}')$$,'owner can share with one member');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','role','authenticated','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid)::text,true);
select is(jsonb_array_length(public.train_command('get',current_setting('test.train')::uuid)->'locations'),1,'selected member sees precise fix');
select throws_ok($$select public.train_command('update',current_setting('test.train')::uuid,'{"name":"Changed","symbol":"X","visibility":"public"}')$$,'42501','group_admin_required','member cannot publish group');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000003','role','authenticated','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000003')::uuid)::text,true);
select is(public.train_command('list'),'[]'::jsonb,'outsider cannot enumerate private trains');
select throws_ok($$select public.train_command('get',current_setting('test.train')::uuid)$$,'42501','active_group_membership_required','outsider cannot read private payload');
select throws_ok($$select public.reserve_media_upload('group',current_setting('test.train')::uuid,'image')$$,'42501','media_target_unavailable','outsider cannot upload group media');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','role','authenticated','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid)::text,true);
select lives_ok($$select public.train_command('update',current_setting('test.train')::uuid,'{"name":"Test train","symbol":"🚂","visibility":"public"}')$$,'owner can publish train');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000003','role','authenticated','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000003')::uuid)::text,true);
select is(jsonb_array_length(public.train_command('list')),1,'public metadata is discoverable');
select throws_ok($$select public.train_command('get',current_setting('test.train')::uuid)$$,'42501','active_group_membership_required','public metadata does not expose private payload');
select lives_ok($$select public.train_command('join',current_setting('test.train')::uuid)$$,'public train can be joined');
select is(jsonb_array_length(public.train_command('get',current_setting('test.train')::uuid)->'locations'),0,'new member does not gain access to old location share');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','role','authenticated','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid)::text,true);
select lives_ok($$select public.group_action(current_setting('test.train')::uuid,'leave')$$,'member can leave');
select lives_ok($$select public.train_command('join',current_setting('test.train')::uuid)$$,'former member can rejoin public train');
select is(jsonb_array_length(public.train_command('get',current_setting('test.train')::uuid)->'locations'),0,'rejoining does not resurrect old location access');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','role','authenticated','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid)::text,true);
select lives_ok($$select public.train_command('stop_location',current_setting('test.train')::uuid)$$,'sharing can be stopped');
select is(jsonb_array_length(public.train_command('get',current_setting('test.train')::uuid)->'locations'),0,'stopping removes exact fix');
select is((public.discovery_allowance()->>'limit')::integer,20,'free allowance is 20');
select lives_ok($$select * from public.discover_nearby('{}',null)$$,'initial selection loads');
select lives_ok($$select public.discovery_allowance(true)$$,'one deliberate refresh allowed');
select lives_ok($$select * from public.discover_nearby('{}',null)$$,'replacement selection loads');
select throws_ok($$select public.discovery_allowance(true)$$,'P0001','daily_discovery_refresh_unavailable','second refresh is rejected server-side');
reset role;
update private.discovery_batches set refreshed_on=current_date-1 where profile_id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','role','authenticated','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid)::text,true);
select lives_ok($$select public.discovery_allowance(true)$$,'allowance resets next calendar day');
reset role;
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select md5('train-discovery:'||n)::uuid,'authenticated','authenticated','train-'||n||'@example.test',now(),'{"provider":"email","providers":["email"]}','{}',now(),now() from generate_series(1,35)n;
update public.profiles set display_name='Synthetic discovery',date_of_birth='1995-01-01',identity_tags=array['gay'],looking_for=array['chat'],
 bio='Test',region='hofudborgarsvaedid',terms_accepted_version='2026-08-31',terms_accepted_at=now(),privacy_accepted_version='2026-08-31',privacy_accepted_at=now(),
 guidelines_accepted_version='2026-08-31',guidelines_accepted_at=now(),special_category_consent_at=now(),onboarding_completed_at=now(),last_active_at=now()
 where id in(select md5('train-discovery:'||n)::uuid from generate_series(1,35)n);
insert into private.private_locations(profile_id,cell_center,verified_at,last_submission_at,rate_window_started_at,rate_window_count)
select md5('train-discovery:'||n)::uuid,extensions.st_setsrid(extensions.st_makepoint(-21.94,64.15),4326)::extensions.geography,now(),now(),now(),1 from generate_series(1,35)n;
set local role authenticated;
select is((select count(*) from public.discover_nearby('{"limit":10000}',null)),20::bigint,'oversized requested limit still yields only 20');
select set_config('test.selection',(select jsonb_agg(profile_id)::text from public.discover_nearby('{}',null)),true);
select is((select jsonb_agg(profile_id)::text from public.discover_nearby('{}',null)),current_setting('test.selection'),'ordinary reload preserves selected IDs');
select is((select count(*) from public.discover_nearby('{"_allowed_ids":[],"_excluded_ids":[]}',null)),20::bigint,'injected internal filters cannot change selection');
select * from finish();
rollback;
